using System;using System.IO;using System.Linq;using Game.Runtime;using Game.Components;using Unity.Entities;using Unity.Collections;using Unity.Transforms;using Unity.Mathematics;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
// Owner-change regression controls, not per-configuration smoke or native mission evidence.
internal static class NativeParentCleanupControls{
 static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 static void Save(string path,JObject value){using var f=new FileStream(path,FileMode.CreateNew);using var w=new StreamWriter(f);w.Write(value.ToString(Formatting.Indented));}
 static int Main(string[] args){if(args.Length!=1)throw new ArgumentException("One fresh result JSON path required");return RunParentCleanupControls(args[0]);}
 internal static int RunParentCleanupControls(string output){var cases=new JArray();void Case(string name,Action test){test();cases.Add(new JObject{["case"]=name,["passed"]=true});}Entity E(int i,int version=1)=>new Entity{Index=i,Version=version};EntityManager M(params Entity[] rows){var em=new EntityManager();foreach(var e in rows)em.ImportEntity(e);return em;}void Ghost(EntityManager em,Entity e)=>em.AddComponentData(e,new CleanupEntity());void Apply(EntityManager em){var plan=em.PlanSourceNativeParentCleanup();em.ApplySourceNativeParentCleanup(plan);}void Reject(Action action,string reason){try{action();}catch(Exception error){Check(error.Message.Contains(reason),"Exact intended rejection: "+error);return;}throw new Exception("Expected rejection: "+reason);}
 Case("actual consumed-source readset",()=>SourceTransformConsumedReadset.VerifyForCurrentImage().RequireCurrent());
 Case("changed readset rejected at original boundary",()=>{var invalid=output+".invalid-readset.json";using(var stream=new FileStream(invalid,FileMode.CreateNew))using(var writer=new StreamWriter(stream))writer.Write("{}");Reject(()=>SourceTransformConsumedReadset.VerifyAtBoundary(invalid),"Unreviewed transform consumed-owner readset");});
 foreach(bool meta in new[]{false,true})Case(meta?"default meta-chunk exclusion":"default system exclusion",()=>{var e=E(1);var em=M(e);Ghost(em,e);em.AddBuffer<Child>(e);if(meta)em.AddComponentData(e,new Unity.Entities.ChunkHeader());else em.AddComponentData(e,new Unity.Entities.SystemInstance());Apply(em);Check(em.HasBuffer<Child>(e),"Same existing SDK HasComponentNamed default exclusions; private marker DTO presence only");});
 Case("witness819 ordinary payload retained and empty siblings retire",()=>{var root=E(818);var child=E(819);var leaf=E(820);var em=M(root,child,leaf);foreach(var e in new[]{root,child,leaf})Ghost(em,e);em.AddBuffer<Child>(root).Add(new Child{Value=child});em.AddBuffer<Child>(child).Add(new Child{Value=leaf});em.AddComponentData(child,new PreviousParent{Value=root});em.AddComponentData(leaf,new PreviousParent{Value=child});using(var ecb=new EntityCommandBuffer(Allocator.Temp)){ecb.AddComponent(child,new UnitPathRequest{Goal=new int2(0,0)});ecb.Playback(em);}Apply(em);Check(em.Exists(child)&&em.HasComponent<CleanupEntity>(child)&&em.GetComponentData<UnitPathRequest>(child).Goal.Equals(new int2(0,0))&&!em.HasBuffer<Child>(child)&&!em.HasComponent<PreviousParent>(child)&&!em.Exists(root)&&!em.Exists(leaf),"Witness payload/entity and exact empty retirement");});
 Case("unrelated ghost and blocker stay owned elsewhere",()=>{var e=E(1);var em=M(e);Ghost(em,e);em.AddComponentData(e,new StaticBlockerPrevBounds());em.AddComponentData(e,new UnitPathRequest{Goal=new int2(12,-7)});Apply(em);Check(em.Exists(e)&&em.HasComponent<StaticBlockerPrevBounds>(e)&&em.GetComponentData<UnitPathRequest>(e).Goal.Equals(new int2(12,-7)),"Unrelated components untouched");});
 Case("Child plus LocalToWorld excluded",()=>{var e=E(1);var em=M(e);Ghost(em,e);em.AddComponentData(e,new LocalToWorld());em.AddBuffer<Child>(e);Apply(em);Check(em.HasBuffer<Child>(e),"Native deleted query exclusion");});
 Case("PreviousParent plus Parent excluded",()=>{var e=E(1);var em=M(e);Ghost(em,e);em.AddComponentData(e,new PreviousParent{Value=E(2)});em.AddComponentData(e,new Parent{Value=E(2)});Apply(em);Check(em.HasComponent<PreviousParent>(e)&&em.HasComponent<Parent>(e),"Native removed query exclusion");});
 foreach(bool prefab in new[]{false,true})Case(prefab?"Prefab default excluded":"Disabled default excluded",()=>{var e=E(1);var em=M(e);Ghost(em,e);em.AddBuffer<Child>(e);if(prefab)em.AddComponentData(e,new Prefab());else em.AddComponentData(e,new Disabled());Apply(em);Check(em.HasBuffer<Child>(e),"Original default query exclusions");});
 Case("matched current Parent removes only relationships",()=>{var p0=E(1);var c=E(2);var em=M(p0,c);Ghost(em,p0);em.AddBuffer<Child>(p0).Add(new Child{Value=c});em.AddComponentData(c,new Parent{Value=p0});em.AddComponentData(c,new PreviousParent{Value=p0});em.AddComponentData(c,new UnitPathRequest{Goal=new int2(-4,9)});Apply(em);Check(!em.Exists(p0)&&em.Exists(c)&&!em.HasComponent<Parent>(c)&&!em.HasComponent<PreviousParent>(c)&&em.GetComponentData<UnitPathRequest>(c).Goal.Equals(new int2(-4,9)),"Matched relationship-only removal");});
 Case("cross-parent relation preserved",()=>{var p0=E(1);var p1=E(3);var c=E(2);var em=M(p0,p1,c);Ghost(em,p0);em.AddBuffer<Child>(p0).Add(new Child{Value=c});em.AddComponentData(c,new Parent{Value=p1});em.AddComponentData(c,new PreviousParent{Value=p1});Apply(em);Check(!em.Exists(p0)&&em.GetComponentData<Parent>(c).Value==p1&&em.GetComponentData<PreviousParent>(c).Value==p1,"Mismatched current Parent untouched");});
 Case("stale parent version does not unlink replacement",()=>{var child=E(1);var replacement=E(2,2);var em=M(child,replacement);Ghost(em,child);em.AddComponentData(child,new PreviousParent{Value=E(2,1)});em.AddComponentData(replacement,new LocalToWorld());em.AddBuffer<Child>(replacement).Add(new Child{Value=child});Apply(em);Check(!em.Exists(child)&&em.HasBuffer<Child>(replacement)&&em.GetBuffer<Child>(replacement).Length==1,"No entity-index alias across Version");});
 Case("stale Child version does not touch replacement",()=>{var parent=E(1);var replacement=E(2,2);var em=M(parent,replacement);Ghost(em,parent);em.AddBuffer<Child>(parent).Add(new Child{Value=E(2,1)});em.AddComponentData(replacement,new Parent{Value=parent});em.AddComponentData(replacement,new PreviousParent{Value=parent});Apply(em);Check(!em.Exists(parent)&&em.HasComponent<Parent>(replacement)&&em.HasComponent<PreviousParent>(replacement),"Stale child identity remains distinct");});
 Case("missing membership rejected atomically before all writes",()=>{var parent=E(1);var child=E(2);var earlier=E(3);var em=M(parent,child,earlier);em.AddComponentData(parent,new LocalToWorld());em.AddBuffer<Child>(parent);Ghost(em,child);em.AddComponentData(child,new PreviousParent{Value=parent});Ghost(em,earlier);em.AddBuffer<Child>(earlier);int v=em.StructuralVersion;Reject(()=>em.PlanSourceNativeParentCleanup(),"Child entity not in parent");Check(em.StructuralVersion==v&&em.Exists(earlier)&&em.HasBuffer<Child>(earlier)&&em.HasComponent<PreviousParent>(child),"Plan validates before mutation");});
 Case("original phase clock rejects repeated frame",()=>{var clock=new SourceTransformPhaseClock();clock.Enter(1);Reject(()=>clock.Enter(1),"frame");});
 var result=new JObject{["kind"]="PrivateNativeParentCleanupOwnerControls",["passed"]=true,["cases"]=cases,["world_created"]=false,["source_ids_allocated"]=0,["scope"]="Reconstructed actual819 state through SAME original EntityManager and Plan/Apply. No World/mission/offender/native-execution claim."};Save(output,result);Console.WriteLine("[NativeParentCleanupControls] result=Passed checks="+cases.Count+" world=False");return 0;}
}
// Private control-only marker DTOs test existing SDK FullName exclusions; no native system/chunk implementation claim.
namespace Unity.Entities{internal struct SystemInstance:IComponentData{}internal struct ChunkHeader:IComponentData{}}
